var msg_payload = msg.payload;

if (msg_payload.scene_name === 'IGK6-demo-room') {
    var region_name = msg_payload.region_name;
    var timestamp = msg_payload.timestamp;
    var counts = msg_payload.counts;
    var count_keys = Object.keys(counts);

    count_keys.forEach(function (key) {
        var json_body = [
            { count: counts[key] + "i" },
            {
                location: "IGK6",
                region: region_name,
                object: key
            }
        ];
        node.send({ payload: json_body, measurement: "region_obj_count_2", timestamp: timestamp });
    });

    var objects_exited = msg_payload.exited;
    var items_exited = objects_exited.length;
    if (items_exited > 0) {
        objects_exited.forEach(function (obj) {
            var json_body2 = [
                { dwell_time: parseFloat(obj.dwell.toFixed(2)) },
                {
                    location: "IGK6",
                    region: region_name,
                    object: obj.object.category
                }
            ];
            node.send({ payload: json_body2, measurement: "region_obj_dwell_2", timestamp: timestamp });
        });
    }
}
return null;

var msg_payload = msg.payload;

if (msg_payload.name === 'IGK6-demo-room') {
    var timestamp = msg_payload.timestamp;
    // Handle person tracking data
    if (msg_payload.objects && Array.isArray(msg_payload.objects)) {
        msg_payload.objects.forEach(function (obj) {
            if (obj.category === "person" && ("lat_long_alt" in obj)) {
                // Calculate speed (velocity magnitude)
                var vel = obj.velocity || [0, 0, 0];
                var speed = Math.sqrt(vel[0] * vel[0] + vel[1] * vel[1] + vel[2] * vel[2]);

                var json_body3 = [
                    {
                        obj_id: obj.id,
                        latitude: obj.lat_long_alt ? obj.lat_long_alt[0] : 0,
                        longitude: obj.lat_long_alt ? obj.lat_long_alt[1] : 0,
                        heading: obj.heading || 0,
                        velocity: speed.toFixed(2)
                    },
                    {
                        location: "IGK6"
                    }
                ];

                node.send({
                    payload: json_body3,
                    measurement: "person_loc",
                    timestamp: timestamp
                });
            }
        });
    }
}
return null;

var msg_payload = msg.payload;

if (msg_payload.scene_name === 'IGK6-demo-room') {
    var tripwire_name = msg_payload.tripwire_name;
    var timestamp = msg_payload.timestamp;
    var objects = msg_payload.objects;

    // Count persons crossing in each direction
    var count_forward = 0;  // direction +1
    var count_backward = 0; // direction -1

    if (objects && Array.isArray(objects)) {
        objects.forEach(function (obj) {
            if (obj.category === 'person') {
                if (obj.direction === 1) {
                    count_forward++;
                } else if (obj.direction === -1) {
                    count_backward++;
                }
            }
        });
    }

    // Send forward direction count
    if (count_forward > 0) {
        var json_body_forward = [
            { count: count_forward + "i" },
            {
                location: "IGK6",
                tripwire: tripwire_name,
                object: "person",
                direction: "forward"
            }
        ];
        node.send({ 
            payload: json_body_forward, 
            measurement: "tripwire_crossings", 
            timestamp: timestamp 
        });
    }

    // Send backward direction count
    if (count_backward > 0) {
        var json_body_backward = [
            { count: count_backward + "i" },
            {
                location: "IGK6",
                tripwire: tripwire_name,
                object: "person",
                direction: "backward"
            }
        ];
        node.send({ 
            payload: json_body_backward, 
            measurement: "tripwire_crossings", 
            timestamp: timestamp 
        });
    }
}
return null;

// Simple NLQ processor - handles basic patterns only
const query = msg.payload.query || "";
const q = query.toLowerCase();
const bucket = env.get("INFLUX_BUCKET") || "SS-Anthem";

let flux = "";
let summary = "";

// Determine time range
let timeRange = "-1h";
let timeDesc = "last hour";
if (q.includes("last") && q.includes("hour")) {
    timeRange = "-1h";
    timeDesc = "last hour";
} else if (q.includes("5 minute") || q.includes("five minute")) {
    timeRange = "-5m";
    timeDesc = "last 5 minutes";
} else if (q.includes("today") || q.includes("24 hour")) {
    timeRange = "-24h";
    timeDesc = "last 24 hours";
}

// Pattern matching for queries
if (q.includes("person") && (q.includes("count") || q.includes("how many"))) {
    // Person count in regions
    if (q.includes("waiting") || q.includes("waiting area")) {
        flux = `from(bucket:"${bucket}") |> range(start:${timeRange}) |> filter(fn:(r)=> r._measurement == "region_obj_count_2" and r.object == "person" and r.region == "waiting_area")`;
        summary = `Showing person count in waiting area for the ${timeDesc}.`;
    } else {
        flux = `from(bucket:"${bucket}") |> range(start:${timeRange}) |> filter(fn:(r)=> r._measurement =~ /region_obj_count/ and r.object == "person")`;
        summary = `Showing person count data for the ${timeDesc}.`;
    }
} else if (q.includes("dwell") || (q.includes("time") && q.includes("spent"))) {
    // Dwell time queries
    flux = `from(bucket:"${bucket}") |> range(start:${timeRange}) |> filter(fn:(r)=> r._measurement =~ /dwell/ and r.object == "person")`;
    summary = `Showing dwell time data for the ${timeDesc}.`;
} else if (q.includes("tripwire") || q.includes("crossing") || q.includes("checkout")) {
    // Tripwire crossings
    flux = `from(bucket:"${bucket}") |> range(start:${timeRange}) |> filter(fn:(r)=> r._measurement == "tripwire_crossings")`;
    summary = `Showing tripwire crossings for the ${timeDesc}.`;
} else if (q.includes("event") || q.includes("activity") || q.includes("analytics")) {
    // All analytics/events
    flux = `from(bucket:"${bucket}") |> range(start:${timeRange})`;
    summary = `Showing all analytics data for the ${timeDesc}.`;
} else if (q.includes("waiting") && q.includes("area")) {
    // Waiting area specific
    flux = `from(bucket:"${bucket}") |> range(start:${timeRange}) |> filter(fn:(r)=> r.region == "waiting_area")`;
    summary = `Showing waiting area analytics for the ${timeDesc}.`;
} else {
    // Default fallback - show recent data
    flux = `from(bucket:"${bucket}") |> range(start:${timeRange}) |> limit(n:100)`;
    summary = `Showing recent analytics data from the ${timeDesc} (limited to 100 records).`;
}

msg.payload = {
    success: true,
    flux_query: flux,
    summary: summary,
    original_query: query
};

return msg;
